<script setup lang="ts">
import {computed,ref} from 'vue'
import {useRoute} from 'vue-router'
import {useDb} from '../../../stores/db'
import {useSession} from '../../../stores/session'
import {StatusBadge,PreviewBanner} from '../../../components/shared'
import {fmtMoney} from '../../../lib/money'
import {postFeeInstalment,reverseFee,prepareRemittance,approveRemittance,executeRemittance,markRemittanceUnknown,suspendRemittanceForPayeeChange,markPaid,campaignAvailable,campaignSplit} from '../domain'
const route=useRoute(),db=useDb(),session=useSession(),tab=ref(String(route.query.tab||'queues')),message=ref(''),allocation=ref(1000000),feeOrder=ref<'before'|'after'>('after'),feeChoice=ref(false)
const feeNet=computed(()=>db.data.feeEntries.reduce((sum,entry)=>sum+entry.feeMinor,0))
const allocationTotal=computed(()=>db.data.allocations.filter(a=>a.verified).reduce((sum,a)=>sum+a.amountMinor,0))
const outstanding=computed(()=>(db.data.bills[0]?.amountMinor??0)-allocationTotal.value)
const campaign=computed(()=>db.data.campaigns[0]),available=computed(()=>campaign.value?campaignAvailable(campaign.value):0),split=computed(()=>campaignSplit(allocation.value,feeOrder.value==='before'))
function run(fn:()=>unknown){try{const result=fn();message.value=result?JSON.stringify(result):'Updated.'}catch(e){message.value=e instanceof Error?e.message:''}}
</script>
<template><div class="page"><header class="page-header"><div><p class="eyebrow">Finance and ledger</p><h1>Finance</h1><p>Obligations, receipts, remittances and reconciliation remain separate.</p></div><StatusBadge :label="session.activePersona?.activeRole||'Unknown'"/></header><p v-if="message" class="card">{{message}}</p><div class="actions"><el-button v-for="name in ['queues','fees','remittance','refunds','bills','reconciliation','accounting','jv','campaign']" :key="name" :type="tab===name?'primary':''" @click="tab=name">{{name}}</el-button></div><section v-if="tab==='queues'" class="card-grid"><article v-for="queue in ['Missing evidence','Approval','Eligible payables','Payment exceptions','Reconciliation']" :key="queue" class="card"><h3>{{queue}}</h3><strong class="kpi-value">{{queue==='Payment exceptions'?1:0}}</strong><StatusBadge label="Scope checked"/></article></section><section v-else-if="tab==='fees'" class="card"><h2>PIVO B2B fee</h2><p>Net RM500,000 at 10% deal commission = RM50,000 eligible commission; PIVO fee RM5,000; agency RM45,000.</p><div class="card-grid"><article><span class="source-meta">Approved fee</span><strong>{{fmtMoney(500000)}}</strong></article><article><span class="source-meta">Posted net</span><strong>{{fmtMoney(feeNet)}}</strong></article><article><span class="source-meta">Agency amount</span><strong>{{fmtMoney(4500000)}}</strong></article></div><div class="actions"><el-button @click="run(()=>postFeeInstalment(2000000,200000,'instalment-2'))">Post second instalment</el-button><el-button @click="run(()=>postFeeInstalment(2000000,200000,'instalment-2'))">Retry same event</el-button><el-button @click="run(()=>reverseFee('fee-post-1',1000000,100000,'Partial correction'))">Partial reversal</el-button><el-button @click="run(()=>reverseFee('fee-post-1',4000000,400000,'Remaining correction'))">Remaining reversal</el-button></div><p>Reversals are append-only linked entries. Paid cash recovery is tracked separately.</p></section><section v-else-if="tab==='remittance'" class="card"><h2>Booking-fee remittance</h2><p v-for="remit in db.data.remittances" :key="remit.id"><StatusBadge :label="remit.state"/> {{fmtMoney(remit.amountMinor)}} · {{remit.payee.name}} {{remit.payee.accountMasked}} · key {{remit.idempotencyKey}}</p><div class="actions"><el-button @click="run(prepareRemittance)">Prepare</el-button><el-button @click="run(approveRemittance)">Approve</el-button><el-button @click="run(executeRemittance)">Execute</el-button><el-button @click="run(markRemittanceUnknown)">Mark unknown</el-button><el-button :disabled="db.data.remittances[0]?.state==='unknown'" @click="run(executeRemittance)">Retry</el-button><el-button @click="run(suspendRemittanceForPayeeChange)">Change payee details</el-button><el-button @click="run(()=>markPaid(true))">Mark paid with evidence</el-button><el-button @click="run(()=>markPaid(false))">Mark paid without evidence</el-button></div><p class="preview-banner">Never send twice. Manual evidence route until a bank connection is verified.</p></section><section v-else-if="tab==='refunds'" class="card"><h2>Refunds</h2><el-table :data="db.data.refunds"><el-table-column prop="reason" label="Reason"/><el-table-column label="State"><template #default="{row}"><StatusBadge :label="row.state"/></template></el-table-column><el-table-column label="Entitlement"><template #default="{row}">{{fmtMoney(row.entitlementMinor??null)}}</template></el-table-column></el-table><p>Cancellation request, case cancellation, inventory release and payment each need separate authority and evidence.</p></section><section v-else-if="tab==='bills'" class="card"><h2>Purchase bills</h2><p class="data-row"><span>Bill</span><strong>{{fmtMoney(db.data.bills[0]?.amountMinor??null)}}</strong></p><p class="data-row"><span>Verified allocations</span><strong>{{fmtMoney(allocationTotal)}}</strong></p><p class="data-row"><span>Outstanding</span><strong>{{fmtMoney(outstanding)}}</strong></p><p>Only verified allocations reduce the bill. A screenshot is pending evidence.</p></section><section v-else-if="tab==='reconciliation'" class="card"><h2>Reconciliation</h2><p>Expected gross, provider charges and observed net are compared independently.</p><div class="data-list"><article class="data-row"><span>Unknown payment</span><StatusBadge label="Unknown" tone="unknown"/></article><article class="data-row"><span>Out-of-order old event</span><StatusBadge label="Ignored safely"/></article></div></section><section v-else-if="tab==='accounting'" class="card"><PreviewBanner/><h2>AutoCount (official book)</h2><p>Queue → Send → Post → Reconcile. API acceptance alone never proves a posted entry.</p><p class="preview-banner">TO CONFIRM · AutoCount edition per entity</p></section><section v-else-if="tab==='jv'" class="card"><h2>JV and capital</h2><div class="card-grid"><article><span class="source-meta">Budget</span><strong>{{fmtMoney(500000000)}}</strong></article><article><span class="source-meta">Commitments</span><strong>{{fmtMoney(350000000)}}</strong></article><article><span class="source-meta">Forecast remaining</span><strong>{{fmtMoney(150000000)}}</strong></article></div><p>Sale proceeds and deposits cannot become advertising profit or guaranteed investor return.</p></section><section v-else class="card"><PreviewBanner/><h2>Campaign ledger</h2><p>Available to commit: <strong>{{fmtMoney(available)}}</strong></p><div class="card-grid"><label>Allocation (sen)<input v-model.number="allocation" type="number"></label><label>Fee order<select v-model="feeOrder"><option value="after">After AIVO fee</option><option value="before">Before AIVO fee</option></select></label></div><p>AIVO {{fmtMoney(split.aivoFee)}} · pool {{fmtMoney(split.pool)}} · lead provider {{fmtMoney(split.lead)}} · leader {{fmtMoney(split.leader)}} · investor {{fmtMoney(split.investor)}} · caller/closer {{fmtMoney(split.caller)}} each</p><label><input v-model="feeChoice" type="checkbox"> Terms recorded with approver</label><el-button :disabled="!feeChoice">Lock terms before launch</el-button></section></div></template>
